import {escapeHtml as h,number} from './domain.js';
import {badge,shipArt} from './art.js';
import {sumForces,forceCamps} from './operations.js';
const units=[['soldiers','Soldats'],['scouts','Scouts'],['bombers','Bombardiers'],['fighters','Destroyers']];
export function detailForceSummary(location,owned){
 const p={...location,forces:location.forces?.length?location.forces:owned?[{...owned,is_own:true,kind:'reserve',mission:'defend',ground_soldiers:owned.soldiers,soldiers:0}]:[]},totals=forceCamps(p),side=p.stance==='attack'?'attack':'defend';
 const camps=[{key:'own',name:'Vous',match:f=>f.is_own},...(['allies','enemies'].filter(k=>units.some(([u])=>totals[k][u]>0)).map(key=>({key,name:p.stance==='mixed'?(key==='allies'?'Autres : défense':'Autres : attaque'):(key==='allies'?'Alliés':'Ennemis'),match:f=>!f.is_own&&(key==='allies'?f.mission===side:f.mission!==side)})))];
 const reserve=sumForces(p.forces.filter(f=>f.is_own&&f.kind==='reserve')),fleet=sumForces(p.forces.filter(f=>f.is_own&&f.kind!=='reserve'));
 const cells=(key,forces)=>{const own=sumForces(forces.filter(camps[0].match)),r=sumForces(forces.filter(f=>f.is_own&&f.kind==='reserve')),f=sumForces(forces.filter(f=>f.is_own&&f.kind!=='reserve'));return [own[key],r[key],f[key],...camps.slice(1).map(c=>sumForces(forces.filter(c.match))[key])];};
 const cell=(value,i)=>`<span class="${i===1?'reserve':i>2?camps[i-2].key:'own'} ${value?'':'zero'}">${number(value)}</span>`;
 return `<section class="detail-force-summary" style="--force-columns:${camps.length+2}"><div class="detail-panel-heading"><span class="eyebrow">FORCES PRÉSENTES</span><h2>Rapport de force</h2><small>Réserves et flottes comprises · détail par race</small></div><div class="detail-force-scroll"><div class="detail-force-grid detail-force-head"><span>Unités</span><span>Total</span><span>Réserves</span><span>En flotte</span>${camps.slice(1).map(c=>`<span class="${c.key}">${h(c.name)}</span>`).join('')}</div>${units.map(([key,label])=>{const races=['elys','vael','khar'].map(race=>({race,values:cells(key,p.forces.filter(f=>(f.race||p.race)===race))})).filter(r=>r.values.some(v=>v>0));return `<details class="detail-unit"><summary class="detail-force-grid"><span class="detail-unit-name"><i aria-hidden="true">›</i>${key==='soldiers'?badge('race',p.race):shipArt(p.race,key==='scouts'?'scout':key==='bombers'?'bomber':'fighter')}${label}</span>${[totals.own[key],reserve[key],fleet[key],...camps.slice(1).map(c=>totals[c.key][key])].map(cell).join('')}</summary><div class="detail-unit-races">${races.map(r=>`<div class="detail-force-grid"><span>${badge('race',r.race)}${h(r.race.charAt(0).toUpperCase()+r.race.slice(1))}</span>${r.values.map(cell).join('')}</div>`).join('')||'<p>Aucune unité présente.</p>'}</div></details>`;}).join('')}</div><p class="detail-force-note">Vos soldats : ${number(totals.own.ground)} au sol · ${number(totals.own.embarked)} embarqués.</p></section>`;
}
export function fleetCommandCenter(fleets){
 const ships=fleets.filter(f=>Number(f.scouts)+Number(f.bombers)+Number(f.fighters)>0);
 return `<section class="fleet-command-center"><div class="detail-panel-heading"><span class="eyebrow">COMMANDEMENT</span><h2>Donner un ordre</h2></div>${ships.length?`<label class="field">Flotte constituée<select id="fleet-command-choice">${ships.map(f=>`<option value="${h(f.id)}">${h(f.name)} · ${number(Number(f.scouts)+Number(f.bombers)+Number(f.fighters))} vaisseaux</option>`).join('')}</select></label><div id="mission-orders" class="mission-orders"></div>`:'<p class="empty">Constituez une flotte avec des vaisseaux pour lui donner un ordre de déplacement.</p><div id="mission-orders" class="mission-orders" hidden></div>'}</section>`;
}
